import{_ as s,a8 as a,o as i,c as o,ah as n,K as e}from"./chunks/framework.D4nPdsp1.js";import"./chunks/theme.OdUOsJ8d.js";const A=JSON.parse('{"title":"EduRAG 双层检索","description":"","frontmatter":{"title":"EduRAG 双层检索","abstract":"EduRAG 教育场景下的双层检索方案，讲解检索层与生成层的协同设计、双层架构如何提升教育问答的准确性与可控性。","created":"2026-07-10T00:00:00.000Z","tags":["大模型","RAG","检索增强生成"],"type":"概念解释","category":["🔍 RAG"]},"headers":[],"relativePath":"vault/Knowledge/AI/EduRAG 双层检索.md","filePath":"vault/Knowledge/AI/EduRAG 双层检索.md","lastUpdated":1790655645000}'),l={name:"vault/Knowledge/AI/EduRAG 双层检索.md"};function h(c,t,b,g,p,_){const d=a("NolebaseGitContributors"),r=a("NolebaseGitChangelog");return i(),o("div",null,[t[0]||(t[0]=n('<h1 id="edurag-双层检索" tabindex="-1">EduRAG 双层检索 <a class="header-anchor" href="#edurag-双层检索" aria-label="Permalink to “EduRAG 双层检索”">​</a></h1><p>EduRAG 是针对教育场景优化的 RAG 架构，通过<strong>粗排 + 精排</strong>两层检索提升答案准确性和教学适配性。</p><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to “架构”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>用户问题 → 粗排（BM25/Embedding）→ 候选文档集 → 精排（教学适配度）→ 最终文档 → LLM 生成答案</span></span></code></pre></div><h2 id="第一层-粗排" tabindex="-1">第一层：粗排 <a class="header-anchor" href="#第一层-粗排" aria-label="Permalink to “第一层：粗排”">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>BM25</td><td>基于词频统计，无需训练</td><td>通用文档检索</td></tr><tr><td>Dense Retrieval</td><td>双塔编码器，语义匹配</td><td>同义表达多的场景</td></tr><tr><td>Hybrid</td><td>BM25 + 向量加权</td><td>兼顾召回和语义</td></tr></tbody></table><h2 id="第二层-精排" tabindex="-1">第二层：精排 <a class="header-anchor" href="#第二层-精排" aria-label="Permalink to “第二层：精排”">​</a></h2><p><strong>教学适配度评分</strong>，综合以下维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>说明</th></tr></thead><tbody><tr><td>知识覆盖度</td><td>候选文档是否覆盖问题核心知识点</td></tr><tr><td>难度匹配</td><td>文档难度是否适合学生当前水平</td></tr><tr><td>教学逻辑性</td><td>文档是否遵循教学顺序（先概念后例题）</td></tr><tr><td>权威性</td><td>来源是否权威（教材 &gt; 百科 &gt; 论坛）</td></tr></tbody></table><h2 id="实现方案" tabindex="-1">实现方案 <a class="header-anchor" href="#实现方案" aria-label="Permalink to “实现方案”">​</a></h2><ul><li><strong>粗排</strong>：Elasticsearch（BM25） + FAISS（向量检索）</li><li><strong>精排</strong>：微调的小模型（如 MiniLM）或规则打分</li><li><strong>缓存</strong>：高频问题缓存检索结果，降低延迟</li></ul><h2 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to “优势”">​</a></h2><p>相比单层检索，双层检索在保证召回率的同时显著提升答案质量，尤其适合教育、医疗等对准确性要求高的垂直领域。</p>',13)),e(d),e(r)])}const f=s(l,[["render",h]]);export{A as __pageData,f as default};
